import 'package:flutter/material.dart';import 'package:flutter_map/flutter_map.dart';import 'package:latlong2/latlong.dart';
class OfflineAwareTileLayer extends StatelessWidget{const OfflineAwareTileLayer({super.key,required this.origin,required this.destination,this.onSourceChanged});final LatLng origin,destination;final ValueChanged<String>? onSourceChanged;@override Widget build(BuildContext context){WidgetsBinding.instance.addPostFrameCallback((_)=>onSourceChanged?.call('ONLINE_OSM'));return TileLayer(urlTemplate:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',userAgentPackageName:'com.udrive.mobile');}}
